-- Disposable test cluster only; all synthetic users are rolled back.
begin;
create function pg_temp.assert_true(condition boolean,label text) returns void language plpgsql as $$
begin if condition is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(statement text,code text,label text) returns void language plpgsql as $$
declare failed boolean:=false;begin begin execute statement;exception when others then if sqlstate<>code then raise exception 'FAIL: % expected % got %',label,code,sqlstate;end if;failed:=true;end;if not failed then raise exception 'FAIL: % unexpectedly succeeded',label;end if;raise notice 'PASS: %',label;end;$$;
insert into auth.users(id) values('00000000-0000-4000-a000-000000000001'),('00000000-0000-4000-a000-000000000002'),('00000000-0000-4000-a000-000000000003');
update public.profiles set username=case id when '00000000-0000-4000-a000-000000000001' then 'alice' when '00000000-0000-4000-a000-000000000002' then 'bob' else 'charlie' end,display_name='Test maker';
insert into public.projects(id,maker_id,name,tagline,description,category_id,status,published_at,publish_request_key,release_url) values
('10000000-0000-4000-a000-000000000001','00000000-0000-4000-a000-000000000001','Following fixture','A shipped following test fixture',repeat('Description. ',20),(select id from public.categories where slug='developer-tools'),'published',now(),gen_random_uuid(),'https://example.test/following');
set local role anon;
select pg_temp.expect_error($q$select public.set_maker_follow('00000000-0000-4000-a000-000000000001',true)$q$,'42501','anonymous follows denied');
select pg_temp.expect_error($q$select * from public.list_projects('following')$q$,'42501','anonymous following feed denied');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select pg_temp.assert_true(public.set_maker_follow('00000000-0000-4000-a000-000000000001',true)='{"followers":1,"following":0,"followed":true}'::jsonb,'active onboarded user can follow without publishing eligibility');
select pg_temp.assert_true(public.set_maker_follow('00000000-0000-4000-a000-000000000001',true)->>'followers'='1','follow retries are idempotent');
select pg_temp.assert_true((select count(*)=1 from public.list_projects('following')),'following includes existing launches');
select pg_temp.assert_true((select count(*)=0 from public.list_projects('following',p_query=>'does not match')),'following search is scoped');
select pg_temp.assert_true((select count(*)=1 from public.list_maker_connections('00000000-0000-4000-a000-000000000001','followers')),'public follower list includes actor');
select pg_temp.expect_error($q$select public.set_maker_follow('00000000-0000-4000-a000-000000000002',true)$q$,'22023','self follows denied');
select pg_temp.expect_error($q$select public.set_maker_follow('00000000-0000-4000-a000-000000000001',null)$q$,'22023','null desired state denied');
select pg_temp.expect_error($q$insert into public.follows(follower_id,following_id) values('00000000-0000-4000-a000-000000000003','00000000-0000-4000-a000-000000000001')$q$,'42501','direct spoofed follows denied');
select pg_temp.assert_true((select count(*)=0 from public.notifications),'actor cannot read recipient notifications');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.notifications),'follow generates one event and no retrospective launch event');
set local role authenticated;
select pg_temp.assert_true(public.set_maker_follow('00000000-0000-4000-a000-000000000001',false)->>'followers'='0','unfollow returns authoritative zero');
select pg_temp.assert_true((select count(*)=0 from public.list_projects('following')),'unfollow immediately removes feed membership');
select public.set_maker_follow('00000000-0000-4000-a000-000000000001',false);
select public.set_maker_follow('00000000-0000-4000-a000-000000000001',true);
reset role;
select pg_temp.assert_true((select count(*)=1 and bool_and(read_at is not null and withdrawn_at is null) from public.notifications),'refollow reuses original read event without spam');
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000001';
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.list_projects('following')),'suspended makers leave following feed');
select pg_temp.assert_true((select count(*)=0 from public.list_maker_connections('00000000-0000-4000-a000-000000000002','following')),'suspended makers leave public lists');
select public.set_maker_follow('00000000-0000-4000-a000-000000000001',false);
select pg_temp.expect_error($q$select public.set_maker_follow('00000000-0000-4000-a000-000000000001',true)$q$,'22023','suspended target cannot be followed');
reset role;
update private.account_controls set status='active' where user_id='00000000-0000-4000-a000-000000000001';
update private.account_settings set notify_follows=false where user_id='00000000-0000-4000-a000-000000000001';
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000003',true);
set local role authenticated;
select public.set_maker_follow('00000000-0000-4000-a000-000000000001',true);
reset role;
select pg_temp.assert_true((select count(*)=1 from public.notifications),'disabled preference prevents new follow event');
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000003';
set local role authenticated;
select pg_temp.expect_error($q$select public.set_maker_follow('00000000-0000-4000-a000-000000000001',false)$q$,'42501','suspended actor cannot mutate');
reset role;
select pg_temp.assert_true(public.get_maker_follow_state('00000000-0000-4000-a000-000000000001')->>'followers'='0','counts exclude suspended followers');
update private.account_controls set status='active' where user_id='00000000-0000-4000-a000-000000000003';
insert into private.rate_limits values('00000000-0000-4000-a000-000000000003','follow',date_trunc('minute',now()),30,now()+interval '2 minutes') on conflict(subject_key,action,window_start) do update set count=30;
set local role authenticated;
select pg_temp.expect_error($q$select public.set_maker_follow('00000000-0000-4000-a000-000000000001',false)$q$,'P0001','follow rate limit enforced');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.follows),'rate limit rolls back mutation');
rollback;
